const conditionalSt = compileStructuredText("IF Start THEN\n IF Permit THEN\n  Motor := TRUE;\n ELSE\n  Motor := FALSE;\n END_IF;\nELSE\n Motor := FALSE;\nEND_IF;", ["Start", "Permit", "Motor"]);
assert.equal(conditionalSt.ok, true, "nested ST IF/ELSE blocks compile");
assert.equal(executeStructuredText(conditionalSt, { Start:true, Permit:true }, {}, ["Motor"]).outputs.Motor, true, "nested ST branches execute the matching body");
assert.equal(executeStructuredText(conditionalSt, { Start:true, Permit:false }, {}, ["Motor"]).outputs.Motor, false, "nested ST else branch executes when its condition is false");
assert.equal(executeStructuredText(conditionalSt, { Start:false, Permit:true }, {}, ["Motor"]).outputs.Motor, false, "outer ST else branch executes when its condition is false");
assert.ok(compileStructuredText("IF Start THEN\nMotor := TRUE;", ["Start", "Motor"]).errors.some((error) => error.includes("missing END_IF")), "unclosed ST conditional is diagnosed");
