assert.equal(executeStructuredText(elsifSt, { Start:false, Permit:true }, {}, ["State"], { State:"INT" }).outputs.State, 2, "ST executes the first matching ELSIF branch");
assert.equal(executeStructuredText(elsifSt, { Start:false, Permit:false }, {}, ["State"], { State:"INT" }).outputs.State, 3, "ST executes ELSE when no branch matches");
assert.ok(compileStructuredText("Motor := Missing;", ["Motor"]).errors.some((error) => error.includes("not declared")), "undeclared ST variables are diagnosed");
